INSERT INTO `tabServer Script` VALUES
('Assembly to Staging','2025-09-30 16:14:15.894634','2025-02-10 18:25:15.553053','Administrator','Administrator',0,0,'API',NULL,'All',NULL,'Before Insert',NULL,0,'EpiBus',0,'# Get context from the action\ncontext = frappe.flags.modbus_context\nif not context:\n    frappe.throw(\"No context provided\")\n    \ndevice = context.get(\'device\')\nparams = context.get(\'params\', {})\n\nbin_number = params.get(\'bin_number\')\nif not bin_number:\n    frappe.log_error(\"Bin number not provided\", \"Staging Robot Error\")\n    frappe.throw(\"Bin number required\")\n    \nfrappe.logger().info(f\"🤖 Starting assembly to staging sequence for bin {bin_number}\")\n\n# Read cycle running status\ncycle_running = device.read_signal(\"CYCLE_RUNNING\")\nif not cycle_running:\n    frappe.log_error(\"PLC cycle not running\", \"Staging Robot Error\")\n    frappe.throw(\"PLC cycle not running\")\n    \n# Set pick bin and source signals\ndevice.write_signal(f\"PICK_BIN_{bin_number}\", True)\ndevice.write_signal(\"FROM_ASSEMBLY\", True)\n\nfrappe.response[\"message\"] = {\n    \"status\": \"success\",\n    \"value\": f\"Initiated assembly to staging sequence for bin {bin_number}\"\n}\n',0,5,86400,NULL,NULL,NULL,NULL),
('Monitor Sequence','2025-09-30 16:14:15.905513','2025-02-10 18:26:16.764389','Administrator','Administrator',0,0,'API',NULL,'All',NULL,'Before Insert',NULL,0,'EpiBus',0,'# Get context from the action\ncontext = frappe.flags.modbus_context\nif not context:\n    frappe.throw(\"No context provided\")\n    \ndevice = context.get(\'device\')\n\n# Check for error signal\nerror_state = device.read_signal(\"PICK_ERROR\")\nif error_state:\n    frappe.log_error(\"Pick error detected\", \"Staging Robot Error\")\n    frappe.throw(\"Pick error detected\")\n    \n# Read completion signals\nto_receiving = device.read_signal(\"PICK_TO_RECEIVING_COMPLETE\")\nto_staging = device.read_signal(\"PICK_TO_STAGING_COMPLETE\")\nto_assembly = device.read_signal(\"PICK_TO_ASSEMBLY_COMPLETE\")\n\nif to_receiving:\n    status = \"Staging to receiving complete\"\nelif to_staging:\n    status = \"Movement to staging complete\"\nelif to_assembly:\n    status = \"Staging to assembly complete\"\nelse:\n    status = \"Sequence in progress\"\n    \nfrappe.logger().info(f\"🤖 Sequence status: {status}\")\n\nfrappe.response[\"message\"] = {\n    \"status\": \"success\",\n    \"value\": status\n}',0,5,86400,NULL,NULL,NULL,NULL),
('Pick List - Move Bin to Pick Pack','2025-09-30 17:45:02.086891','2025-09-30 17:50:02.262482','Administrator','Administrator',0,0,'DocType Event','Pick List','All',NULL,'After Submit',NULL,0,'EpiBus',0,'# Pick List - Move Bin to Pick & Pack\n# Triggered when Pick List is submitted\n# Commands robot to move storage bin to pick & pack station\n\n# Get the first location warehouse (bin to pick from)\nsource_warehouse = None\nif doc.locations:\n    source_warehouse = doc.locations[0].warehouse\n\nif not source_warehouse:\n    frappe.msgprint(\"No pick location found. Robot command skipped.\", indicator=\"orange\")\nelse:\n    # Get connection\n    conn = frappe.get_doc(\"Modbus Connection\", \"Roots Intralogistics Learning Lab\")\n    \n    # Find bin signal by warehouse name\n    bin_signal = None\n    for signal in conn.signals:\n        if signal.warehouse == source_warehouse:\n            bin_signal = signal\n            break\n    \n    # Find TO_PICKPACK_STA_2 signal\n    station_signal = None\n    for signal in conn.signals:\n        if signal.signal_name == \"TO_PICKPACK_STA_2\":\n            station_signal = signal\n            break\n    \n    if not bin_signal:\n        frappe.msgprint(f\"No Modbus signal mapped to warehouse {source_warehouse}. Robot command skipped.\", indicator=\"orange\")\n    elif not station_signal:\n        frappe.msgprint(\"No Modbus signal found for TO_PICKPACK_STA_2. Robot command skipped.\", indicator=\"orange\")\n    else:\n        try:\n            bin_signal.write_signal(True)\n            station_signal.write_signal(True)\n            frappe.msgprint(f\"Robot commanded to move {bin_signal.signal_name} to Pick & Pack Station\")\n        except Exception as e:\n            frappe.msgprint(f\"PLC connection issue. Robot command skipped.\", indicator=\"orange\")\n',0,5,86400,NULL,NULL,NULL,NULL),
('Pick List to Assembly','2025-09-30 16:14:15.916615','2025-02-11 17:08:35.395175','Administrator','Administrator',0,0,'API',NULL,'All',NULL,'Before Insert',NULL,0,'EpiBus',0,'# Pick List to Assembly\n\n# Get context from the action\ncontext = frappe.flags.modbus_context\nif not context:\n    frappe.throw(\"No context provided\")\n    \ndevice = context.get(\'device\')\nparams = context.get(\'params\', {})\n\n# Get bin number from Pick List warehouse\npick_list = frappe.get_doc(\"Pick List\", frappe.form_dict.doc)\nif not pick_list.locations:\n    frappe.msgprint(\"❌ No locations found in Pick List\")\n    frappe.throw(\"No locations found in Pick List\")\n    \nwarehouse = pick_list.locations[0].warehouse\nbin_number = warehouse.replace(\"Pick Bin \", \"\")  # Extract \"01\" from \"Pick Bin 01\"\n\nfrappe.msgprint(f\"🤖 Starting assembly pick sequence for bin {bin_number}\")\n\n# Check cycle running\ncycle_running = device.read_signal(\"CYCLE_RUNNING\")\nif not cycle_running:\n    frappe.msgprint(\"❌ PLC cycle not running\")\n    frappe.throw(\"PLC cycle not running\")\n    \n# Start the sequence\ndevice.write_signal(f\"PICK_BIN_{bin_number}\", True)\ndevice.write_signal(\"TO_ASSEMBLY_STA_1\", True)\n\n# Monitor for in-process signal\nin_process = device.read_signal(\"PICK_TO_ASSEMBLY_IN_PROCESS\")\nif not in_process:\n    frappe.msgprint(\"❌ Pick sequence did not start\")\n    frappe.throw(\"Pick sequence did not start\")\n    \nfrappe.msgprint(\"✅ Pick sequence initiated successfully\")\n\nfrappe.response[\"message\"] = {\n    \"status\": \"success\",\n    \"value\": f\"Assembly pick sequence started for bin {bin_number}\"\n}',0,5,86400,NULL,NULL,NULL,NULL),
('POS Invoice - Move Bin to Pick Pack','2025-09-30 16:14:15.939396','2025-09-30 17:45:23.958711','Administrator','Administrator',0,0,'DocType Event','POS Invoice','All',NULL,'After Submit',NULL,0,'EpiBus',1,'# POS Invoice - Move Bin to Pick & Pack\n# Triggered when POS Invoice is submitted\n# Checks system idle, finds bin with stock, then commands robot to move bin to pick & pack station\n\n# Find which bin has the items (simplified: use first item)\nsource_warehouse = None\nfor item in doc.items:\n    # Query stock ledger to find which bin has this item\n    bins = frappe.get_all(\n        \"Bin\",\n        filters={\n            \"item_code\": item.item_code,\n            \"warehouse\": [\"like\", \"Storage Bin%\"],\n            \"actual_qty\": [\">=\", item.qty]\n        },\n        fields=[\"warehouse\", \"actual_qty\"],\n        order_by=\"actual_qty desc\",\n        limit=1\n    )\n    if bins:\n        source_warehouse = bins[0].warehouse\n        break\n\nif not source_warehouse:\n    frappe.msgprint(\"⚠️ No storage bin found with sufficient stock for POS items. Robot command skipped.\", indicator=\"orange\")\nelse:\n    # Get connection\n    conn = frappe.get_doc(\"Modbus Connection\", \"Roots Intralogistics Learning Lab\")\n    \n    # Find bin signal by warehouse name\n    bin_signal = None\n    for signal in conn.signals:\n        if signal.warehouse == source_warehouse:\n            bin_signal = signal\n            break\n    \n    # Find station signal by explicit signal name\n    station_signal = None\n    for signal in conn.signals:\n        if signal.signal_name == \"TO_PICKPACK_STA_2\":\n            station_signal = signal\n            break\n    \n    if not bin_signal:\n        frappe.msgprint(f\"⚠️ No Modbus signal mapped to warehouse {source_warehouse}. Robot command skipped.\", indicator=\"orange\")\n    elif not station_signal:\n        frappe.msgprint(\"⚠️ No Modbus signal found for TO_PICKPACK_STA_2. Robot command skipped.\", indicator=\"orange\")\n    else:\n        # Write command signals - catch connection errors if PLC is offline\n        try:\n            bin_signal.write_signal(True)\n            station_signal.write_signal(True)\n            frappe.msgprint(f\"✅ Robot commanded to move {bin_signal.signal_name} to Pick & Pack Station\")\n        except Exception as e:\n            frappe.msgprint(f\"⚠️ PLC connection issue. Robot command skipped.\", indicator=\"orange\")\n',0,5,86400,NULL,NULL,NULL,NULL),
('Purchase Receipt - Move Bin to Receiving','2025-09-30 16:14:15.927122','2025-09-30 16:35:35.374790','Administrator','Administrator',0,0,'DocType Event','Purchase Receipt','All',NULL,'After Submit',NULL,0,'EpiBus',0,'# Purchase Receipt - Move Bin to Receiving\n# Triggered when Purchase Receipt is submitted\n# Checks system idle, then commands robot to move bin to receiving station\n\n# Get target warehouse (bin) from first item\ntarget_warehouse = doc.items[0].warehouse if doc.items else None\nif not target_warehouse:\n    frappe.throw(\"Purchase Receipt must specify warehouse for items\")\n\n# Get connection\nconn = frappe.get_doc(\"Modbus Connection\", \"Roots Intralogistics Learning Lab\")\n\n# Find bin signal by warehouse name\nbin_signal = None\nfor signal in conn.signals:\n    if signal.warehouse == target_warehouse:\n        bin_signal = signal\n        break\n\n# Find station signal by explicit signal name\nstation_signal = None\nfor signal in conn.signals:\n    if signal.signal_name == \"TO_RECEIVING_STA_1\":\n        station_signal = signal\n        break\n\nif not bin_signal:\n    frappe.msgprint(f\"⚠️ No Modbus signal mapped to warehouse {target_warehouse}. Robot command skipped.\", indicator=\"orange\")\nelif not station_signal:\n    frappe.msgprint(\"⚠️ No Modbus signal found for TO_RECEIVING_STA_1. Robot command skipped.\", indicator=\"orange\")\nelse:\n    # Write command signals - catch connection errors if PLC is offline\n    try:\n        bin_signal.write_signal(True)\n        station_signal.write_signal(True)\n        frappe.msgprint(f\"✅ Robot commanded to move {bin_signal.signal_name} to Receiving Station\")\n    except Exception as e:\n        frappe.msgprint(f\"⚠️ PLC connection issue. Robot command skipped.\", indicator=\"orange\")\n',0,5,86400,NULL,NULL,NULL,NULL),
('Receiving to Staging','2025-09-30 16:14:15.883855','2025-02-10 18:19:52.532020','Administrator','Administrator',0,0,'API','Modbus Action','All',NULL,'Before Insert',NULL,0,'EpiBus',0,'# Get context from the action\ncontext = frappe.flags.modbus_context\nif not context:\n    frappe.throw(\"No context provided\")\n    \ndevice = context.get(\'device\')\nparams = context.get(\'params\', {})\n\nbin_number = params.get(\'bin_number\')\nif not bin_number:\n    frappe.log_error(\"Bin number not provided\", \"Staging Robot Error\")\n    frappe.throw(\"Bin number required\")\n    \nfrappe.logger().info(f\"🤖 Starting receiving to staging sequence for bin {bin_number}\")\n\n# Read cycle running status\ncycle_running = device.read_signal(\"CYCLE_RUNNING\")\nif not cycle_running:\n    frappe.log_error(\"PLC cycle not running\", \"Staging Robot Error\")\n    frappe.throw(\"PLC cycle not running\")\n    \n# Set pick bin and source signals\ndevice.write_signal(f\"PICK_BIN_{bin_number}\", True)\ndevice.write_signal(\"FROM_RECEIVING\", True)\n\nfrappe.response[\"message\"] = {\n    \"status\": \"success\",\n    \"value\": f\"Initiated receiving to staging sequence for bin {bin_number}\"\n}\n',0,5,86400,NULL,NULL,NULL,NULL),
('Staging to Receiving','2025-09-30 16:14:15.874106','2025-02-10 14:51:15.470891','Administrator','Administrator',0,0,'API','','All',NULL,'Before Insert',NULL,0,'EpiBus',0,'# Get context from the action\ncontext = frappe.flags.modbus_context\nif not context:\n    frappe.throw(\"No context provided\")\n    \ndevice = context.get(\'device\')\nparams = context.get(\'params\', {})\n\nbin_number = params.get(\'bin_number\')\nif not bin_number:\n    frappe.log_error(\"Bin number not provided\", \"Staging Robot Error\")\n    frappe.throw(\"Bin number required\")\n    \nfrappe.logger().info(f\"🤖 Starting staging to receiving sequence for bin {bin_number}\")\n\n# Read cycle running status\ncycle_running = device.read_signal(\"CYCLE_RUNNING\")\nif not cycle_running:\n    frappe.log_error(\"PLC cycle not running\", \"Staging Robot Error\")\n    frappe.throw(\"PLC cycle not running\")\n    \n# Set pick bin and destination signals\ndevice.write_signal(f\"PICK_BIN_{bin_number}\", True)\ndevice.write_signal(\"TO_RECEIVING_STA_1\", True)\n\nfrappe.response[\"message\"] = {\n    \"status\": \"success\",\n    \"value\": f\"Initiated staging to receiving sequence for bin {bin_number}\"\n}',0,5,86400,NULL,NULL,NULL,NULL),
('Storage Warehouse to Receiving','2025-09-30 16:14:15.863394','2025-02-23 19:04:30.122726','Administrator','Administrator',0,0,'API',NULL,'All',NULL,'Before Insert',NULL,0,'EpiBus',0,'# type: ignore\ntry:\n    # Get parameters from the doc\n    docs = frappe.form_dict.get(\'docs\')\n    if not docs:\n        frappe.throw(\"No document data provided\")\n\n    doc = json.loads(str(docs))\n    parameters = doc.get(\'parameters\', [])\n\n    # Extract warehouse parameters\n    warehouse_from = None\n    warehouse_to = None\n\n    for param in parameters:\n        if param.get(\'parameter\') == \"warehouse_from\":\n            warehouse_from = param.get(\'value\')\n        elif param.get(\'parameter\') == \"warehouse_to\":\n            warehouse_to = param.get(\'value\')\n\n    if not warehouse_from or not warehouse_to:\n        frappe.throw(\n            \"Both warehouse_from and warehouse_to parameters are required\")\n\n    # Get the connection from the doc\n    connection = frappe.get_doc(\"Modbus Connection\", doc.get(\'connection\'))\n    if not connection:\n        frappe.throw(\"Modbus Connection not found\")\n\n    # Get the signals from the connection\'s child table\n    signal_from = None\n    signal_to = None\n\n    for signal in connection.signals:\n        if signal.signal_name == warehouse_from:\n            signal_from = signal\n        elif signal.signal_name == warehouse_to:\n            signal_to = signal\n\n    if not signal_from:\n        frappe.throw(\n            f\"Signal {warehouse_from} not found in connection {connection.name}\")\n    if not signal_to:\n        frappe.throw(\n            f\"Signal {warehouse_to} not found in connection {connection.name}\")\n\n    # Write TRUE to both signals using the connection\n    connection.write_signal(signal_from, True)\n    connection.write_signal(signal_to, True)\n\n    # Set success result in frappe.flags\n    frappe.flags.status = \"success\"\n    frappe.flags.value = f\"Successfully set signals for {warehouse_from} and {warehouse_to}\"\n    frappe.flags.error = None\n\nexcept Exception as e:\n    frappe.log_error(f\"Error in storage_warehouse_to_receiving: {str(e)}\")\n    frappe.flags.status = \"error\"\n    frappe.flags.value = None\n    frappe.flags.error = str(e)\n',0,5,86400,NULL,NULL,NULL,NULL),
('Test All Signals - Diagnostic','2025-09-30 15:07:13.559118','2025-09-30 15:11:14.211555','Administrator','Administrator',0,0,'API',NULL,'All',NULL,'Before Insert','epibus.test_all_signals',0,NULL,0,'# Diagnostic Test - Cycle Signals with 4-second delays\n# Uses background jobs to test each signal with proper timing\n\nconnection_id = frappe.form_dict.get(\"connection_id\")\nif not connection_id:\n    frappe.msgprint(\"No connection specified\")\nelse:\n    conn = frappe.get_doc(\"Modbus Connection\", connection_id)\n    writable_types = [\"Digital Output Coil\", \"Analog Output Register\", \"Holding Register\"]\n    \n    # Get all writable signals\n    test_signals = []\n    for signal in conn.signals:\n        if signal.signal_type in writable_types:\n            test_signals.append(signal.name)\n    \n    if not test_signals:\n        frappe.msgprint(\"No writable signals found\")\n    else:\n        frappe.msgprint(\"Starting test on \" + str(len(test_signals)) + \" signals. Each will stay HIGH for 4 seconds. Check server logs for results.\")\n        \n        # Start the background test\n        frappe.enqueue(\n            \"epibus.epibus.doctype.modbus_action.test_signal_sequence.test_signal_sequence\",\n            connection=connection_id,\n            signal_names=test_signals,\n            current_index=0,\n            queue=\"short\",\n            timeout=600\n        )\n',0,5,86400,NULL,NULL,NULL,NULL);
/*!40000 ALTER TABLE `tabServer Script` ENABLE KEYS */;
UNLOCK TABLES;

