('c0nn8aqrr2','2025-09-30 15:10:45.561978','2025-09-30 15:10:45.561978','Administrator','Administrator',0,0,'Server Script','Test All Signals - Diagnostic','{\"added\":[],\"changed\":[[\"script\",\"# Diagnostic Test - Cycle All Signals\\n\\n# Get connection - for API scripts, it\'s passed via frappe.form_dict\\nconnection_id = frappe.form_dict.get(\\\"connection_id\\\")\\nif not connection_id:\\n    frappe.msgprint(\\\"No connection specified\\\")\\nelse:\\n    conn = frappe.get_doc(\\\"Modbus Connection\\\", connection_id)\\n    \\n    results = []\\n    writable_types = [\\\"Digital Output Coil\\\", \\\"Analog Output Register\\\", \\\"Holding Register\\\"]\\n    \\n    for signal in conn.signals:\\n        if signal.signal_type not in writable_types:\\n            continue\\n        \\n        test_result = {\\n            \\\"signal_name\\\": signal.signal_name,\\n            \\\"signal_type\\\": signal.signal_type,\\n            \\\"address\\\": signal.modbus_address\\n        }\\n        \\n        try:\\n            # Read initial\\n            initial = signal.read_signal()\\n            \\n            # Test value\\n            if signal.signal_type == \\\"Digital Output Coil\\\":\\n                test_val = True\\n                reset_val = False\\n            else:\\n                test_val = 100\\n                reset_val = 0\\n            \\n            # Write test\\n            signal.write_signal(test_val)\\n            read_back = signal.read_signal()\\n            \\n            # Check write\\n            if signal.signal_type == \\\"Digital Output Coil\\\":\\n                write_ok = (read_back == test_val)\\n            else:\\n                write_ok = (read_back >= test_val - 1 and read_back <= test_val + 1)\\n            \\n            # Reset\\n            signal.write_signal(reset_val)\\n            final = signal.read_signal()\\n            \\n            # Check reset\\n            if signal.signal_type == \\\"Digital Output Coil\\\":\\n                reset_ok = (final == reset_val)\\n            else:\\n                reset_ok = (final >= reset_val - 1 and final <= reset_val + 1)\\n            \\n            test_result[\\\"status\\\"] = \\\"pass\\\" if (write_ok and reset_ok) else \\\"fail\\\"\\n            \\n        except Exception as e:\\n            test_result[\\\"status\\\"] = \\\"error\\\"\\n            test_result[\\\"error\\\"] = str(e)\\n        \\n        results.append(test_result)\\n    \\n    # Summary\\n    total = len(results)\\n    passed = len([r for r in results if r.get(\\\"status\\\") == \\\"pass\\\"])\\n    failed = len([r for r in results if r.get(\\\"status\\\") == \\\"fail\\\"])\\n    errors = len([r for r in results if r.get(\\\"status\\\") == \\\"error\\\"])\\n    \\n    summary = str(total) + \\\" signals: \\\" + str(passed) + \\\" pass, \\\" + str(failed) + \\\" fail, \\\" + str(errors) + \\\" error\\\"\\n    frappe.msgprint(summary)\\n    \\n    for r in results:\\n        if r[\\\"status\\\"] != \\\"pass\\\":\\n            frappe.msgprint(r[\\\"signal_name\\\"] + \\\": \\\" + r[\\\"status\\\"])\\n\",\"# Diagnostic Test - Cycle Signals with Delay\\n# Sets each signal HIGH, waits 4 seconds (via enqueue), then resets\\n\\nconnection_id = frappe.form_dict.get(\\\"connection_id\\\")\\nif not connection_id:\\n    frappe.msgprint(\\\"No connection specified\\\")\\nelse:\\n    conn = frappe.get_doc(\\\"Modbus Connection\\\", connection_id)\\n    writable_types = [\\\"Digital Output Coil\\\", \\\"Analog Output Register\\\", \\\"Holding Register\\\"]\\n    \\n    # Get all writable signals\\n    test_signals = []\\n    for signal in conn.signals:\\n        if signal.signal_type in writable_types:\\n            test_signals.append(signal.name)\\n    \\n    if not test_signals:\\n        frappe.msgprint(\\\"No writable signals found\\\")\\n    else:\\n        # Start the test by setting first signal\\n        frappe.msgprint(\\\"Starting test on \\\" + str(len(test_signals)) + \\\" signals. Each will stay HIGH for 4 seconds.\\\")\\n        \\n        # Enqueue the test job\\n        frappe.enqueue(\\n            \\\"epibus.epibus.doctype.modbus_action.test_signal_sequence\\\",\\n            connection=connection_id,\\n            signal_names=test_signals,\\n            current_index=0,\\n            job_name=\\\"signal_diagnostic_test\\\",\\n            queue=\\\"short\\\",\\n            timeout=300\\n        )\\n        \\n        frappe.msgprint(\\\"Test started in background. Check logs for results.\\\")\\n\"]],\"data_import\":null,\"removed\":[],\"row_changed\":[],\"updater_reference\":null}',NULL,NULL,NULL,NULL),
