gger().info(f\\\"\\ud83e\\udd16 Commanding robot: {bin_signal.signal_name} + {station_signal.signal_name}\\\")\\n\\n# Write command signals\\nbin_signal.write_signal(True)\\nstation_signal.write_signal(True)\\n\\nfrappe.msgprint(f\\\"\\u2705 Robot commanded to move {bin_signal.signal_name} to Receiving Station\\\")\\n\",\"# Purchase Receipt - Move Bin to Receiving\\n# Triggered when Purchase Receipt is submitted\\n# Checks system idle, then commands robot to move bin to receiving station\\n\\n# Check system idle - all signals must be 0 except PLC_CYCLE_RUNNING\\nconn = frappe.get_doc(\\\"Modbus Connection\\\", \\\"Roots Intralogistics Learning Lab\\\")\\nfor signal in conn.signals:\\n    if signal.signal_name == \\\"PLC_CYCLE_RUNNING\\\":\\n        continue  # OK if running\\n    try:\\n        current_value = signal.read_signal()\\n        if current_value == 1 or current_value == True:\\n            frappe.throw(f\\\"Robot system busy ({signal.signal_name} active). Wait for current operation to complete.\\\")\\n    except:\\n        pass  # Skip signals that can\'t be read\\n\\n# Get target warehouse (bin) from first item\\ntarget_warehouse = doc.items[0].warehouse if doc.items else None\\nif not target_warehouse:\\n    frappe.throw(\\\"Purchase Receipt must specify warehouse for items\\\")\\n\\n# Find bin signal by warehouse name\\nbin_signal = None\\nfor signal in conn.signals:\\n    if signal.warehouse == target_warehouse:\\n        bin_signal = signal\\n        break\\n\\n# Find station signal by explicit signal name (not warehouse, since multiple signals map to same warehouse)\\nstation_signal = None\\nfor signal in conn.signals:\\n    if signal.signal_name == \\\"TO_RECEIVING_STA_1\\\":\\n        station_signal = signal\\n        break\\n\\nif not bin_signal:\\n    frappe.throw(f\\\"No Modbus signal mapped to warehouse {target_warehouse}\\\")\\nif not station_signal:\\n    frappe.throw(\\\"No Modbus signal found for TO_RECEIVING_STA_1\\\")\\n\\n# Write command signals\\nbin_signal.write_signal(True)\\nstation_signal.write_signal(True)\\n\\nfrappe.msgprint(f\\\"\\u2705 Robot commanded to move {bin_signal.signal_name} to Receiving Station\\\")\\n\"]],\"data_import\":null,\"removed\":[],\"row_changed\":[],\"updater_reference\":null}',NULL,NULL,NULL,NULL),
