('s1j7krv5fu','2025-09-30 16:32:43.574113','2025-09-30 16:32:43.574113','Administrator','Administrator',0,0,'Server Script','Purchase Receipt - Move Bin to Receiving','{\"added\":[],\"changed\":[[\"script\",\"# Purchase Receipt - Move Bin to Receiving\\n# Triggered when Purchase Receipt is submitted\\n# Checks system idle, then commands robot to move bin to receiving station\\n\\n# Check system idle - all signals must be 0 except PLC_CYCLE_RUNNING\\nconn = frappe.get_doc(\\\"Modbus Connection\\\", \\\"Roots Intralogistics Learning Lab\\\")\\nfor signal in conn.signals:\\n    if signal.signal_name == \\\"PLC_CYCLE_RUNNING\\\":\\n        continue  # OK if running\\n    try:\\n        current_value = signal.read_signal()\\n        if current_value == 1 or current_value == True:\\n            frappe.throw(f\\\"Robot system busy ({signal.signal_name} active). Wait for current operation to complete.\\\")\\n    except:\\n        pass  # Skip signals that can\'t be read\\n\\n# Get target warehouse (bin) from first item\\ntarget_warehouse = doc.items[0].warehouse if doc.items else None\\nif not target_warehouse:\\n    frappe.throw(\\\"Purchase Receipt must specify warehouse for items\\\")\\n\\n# Find bin signal by warehouse name\\nbin_signal = None\\nfor signal in conn.signals:\\n    if signal.warehouse == target_warehouse:\\n        bin_signal = signal\\n        break\\n\\n# Find station signal by explicit signal name (not warehouse, since multiple signals map to same warehouse)\\nstation_signal = None\\nfor signal in conn.signals:\\n    if signal.signal_name == \\\"TO_RECEIVING_STA_1\\\":\\n        station_signal = signal\\n        break\\n\\nif not bin_signal:\\n    frappe.throw(f\\\"No Modbus signal mapped to warehouse {target_warehouse}\\\")\\nif not station_signal:\\n    frappe.throw(\\\"No Modbus signal found for TO_RECEIVING_STA_1\\\")\\n\\n# Write command signals\\nbin_signal.write_signal(True)\\nstation_signal.write_signal(True)\\n\\nfrappe.msgprint(f\\\"\\u2705 Robot commanded to move {bin_signal.signal_name} to Receiving Station\\\")\\n\",\"# Purchase Receipt - Move Bin to Receiving\\n# Triggered when Purchase Receipt is submitted\\n# Checks system idle, then commands robot to move bin to receiving station\\n\\n# Get target warehouse (bin) from first item\\ntarget_warehouse = doc.items[0].warehouse if doc.items else None\\nif not target_warehouse:\\n    frappe.throw(\\\"Purchase Receipt must specify warehouse for items\\\")\\n\\n# Get connection\\nconn = frappe.get_doc(\\\"Modbus Connection\\\", \\\"Roots Intralogistics Learning Lab\\\")\\n\\n# Find bin signal by warehouse name\\nbin_signal = None\\nfor signal in conn.signals:\\n    if signal.warehouse == target_warehouse:\\n        bin_signal = signal\\n        break\\n\\n# Find station signal by explicit signal name\\nstation_signal = None\\nfor signal in conn.signals:\\n    if signal.signal_name == \\\"TO_RECEIVING_STA_1\\\":\\n        station_signal = signal\\n        break\\n\\nif not bin_signal:\\n    frappe.msgprint(f\\\"\\u26a0\\ufe0f No Modbus signal mapped to warehouse {target_warehouse}. Robot command skipped.\\\", indicator=\\\"orange\\\")\\nelif not station_signal:\\n    frappe.msgprint(\\\"\\u26a0\\ufe0f No Modbus signal found for TO_RECEIVING_STA_1. Robot command skipped.\\\", indicator=\\\"orange\\\")\\nelse:\\n    # Write command signals - catch connection errors if PLC is offline\\n    try:\\n        bin_signal.write_signal(True)\\n        station_signal.write_signal(True)\\n        frappe.msgprint(f\\\"\\u2705 Robot commanded to move {bin_signal.signal_name} to Receiving Station\\\")\\n    except ConnectionError as e:\\n        frappe.msgprint(f\\\"\\u26a0\\ufe0f PLC not connected. Robot command skipped.\\\", indicator=\\\"orange\\\")\\n    except Exception as e:\\n        frappe.msgprint(f\\\"\\u26a0\\ufe0f Failed to send robot command: {str(e)}\\\", indicator=\\\"orange\\\")\\n\"]],\"data_import\":null,\"removed\":[],\"row_changed\":[],\"updater_reference\":null}',NULL,NULL,NULL,NULL),
('s6fm453ufo','2025-09-30 16:32:59.192948','2025-09-30 16:32:59.192948','Administrator','Administrator',0,0,'Server Script','POS Invoice - Move Bin to Pick Pack','{\"added\":[],\"changed\":[[\"script\",\"# POS Invoice - Move Bin to Pick & Pack\\n# Triggered when POS Invoice is submitted\\n# Checks system idle, finds bin with stock, then commands robot to move bin to pick & pack station\\n\\n# Check system idle - all signals must be 0 except PLC_CYCLE_RUNNING\\nconn = frappe.get_doc(\\\"Modbus Connection\\\", \\\"Roots Intralogistics Learning Lab\\\")\\nfor signal in conn.signals:\\n    if signal.signal_name == \\\"PLC_CYCLE_RUNNING\\\":\\n        continue  # OK if running\\n    try:\\n        current_value = signal.read_signal()\\n        if current_value == 1 or current_value == True:\\n            frappe.throw(f\\\"Robot system busy ({signal.signal_name} active). Wait for current operation to complete.\\\")\\n    except:\\n        pass  # Skip signals that can\'t be read\\n\\n# Find which bin has the items (simplified: use first item)\\nsource_warehouse = None\\nfor item in doc.items:\\n    # Query stock ledger to find which bin has this item\\n    bins = frappe.get_all(\\n        \\\"Bin\\\",\\n        filters={\\n            \\\"item_code\\\": item.item_code,\\n            \\\"warehouse\\\": [\\\"like\\\", \\\"Storage Bin%\\\"],\\n            \\\"actual_qty\\\": [\\\">=\\\", item.qty]\\n        },\\n        fields=[\\\"warehouse\\\", \\\"actual_qty\\\"],\\n        order_by=\\\"actual_qty desc\\\",\\n        limit=1\\n    )\\n    if bins:\\n        source_warehouse = bins[0].warehouse\\n        break\\n\\nif not source_warehouse:\\n    frappe.throw(\\\"No storage bin found with sufficient stock for POS items\\\")\\n\\n# Find bin signal by warehouse name\\nbin_signal = None\\nfor signal in conn.signals:\\n    if signal.warehouse == source_warehouse:\\n        bin_signal = signal\\n        break\\n\\n# Find station signal by explicit signal name (not warehouse, since multiple signals map to same warehouse)\\nstation_signal = None\\nfor signal in conn.signals:\\n    if signal.signal_name == \\\"TO_PICKPACK_STA_2\\\":\\n        station_signal = signal\\n        break\\n\\nif not bin_signal:\\n    frappe.throw(f\\\"No Modbus signal mapped to warehouse {source_warehouse}\\\")\\nif not station_signal:\\n    frappe.throw(\\\"No Modbus signal found for TO_PICKPACK_STA_2\\\")\\n\\n# Write command signals\\nbin_signal.write_signal(True)\\nstation_signal.write_signal(True)\\n\\nfrappe.msgprint(f\\\"\\u2705 Robot commanded to move {bin_signal.signal_name} to Pick & Pack Station\\\")\\n\",\"# POS Invoice - Move Bin to Pick & Pack\\n# Triggered when POS Invoice is submitted\\n# Checks system idle, finds bin with stock, then commands robot to move bin to pick & pack station\\n\\n# Find which bin has the items (simplified: use first item)\\nsource_warehouse = None\\nfor item in doc.items:\\n    # Query stock ledger to find which bin has this item\\n    bins = frappe.get_all(\\n        \\\"Bin\\\",\\n        filters={\\n            \\\"item_code\\\": item.item_code,\\n            \\\"warehouse\\\": [\\\"like\\\", \\\"Storage Bin%\\\"],\\n            \\\"actual_qty\\\": [\\\">=\\\", item.qty]\\n        },\\n        fields=[\\\"warehouse\\\", \\\"actual_qty\\\"],\\n        order_by=\\\"actual_qty desc\\\",\\n        limit=1\\n    )\\n    if bins:\\n        source_warehouse = bins[0].warehouse\\n        break\\n\\nif not source_warehouse:\\n    frappe.msgprint(\\\"\\u26a0\\ufe0f No storage bin found with sufficient stock for POS items. Robot command skipped.\\\", indicator=\\\"orange\\\")\\nelse:\\n    # Get connection\\n    conn = frappe.get_doc(\\\"Modbus Connection\\\", \\\"Roots Intralogistics Learning Lab\\\")\\n    \\n    # Find bin signal by warehouse name\\n    bin_signal = None\\n    for signal in conn.signals:\\n        if signal.warehouse == source_warehouse:\\n            bin_signal = signal\\n            break\\n    \\n    # Find station signal by explicit signal name\\n    station_signal = None\\n    for signal in conn.signals:\\n        if signal.signal_name == \\\"TO_PICKPACK_STA_2\\\":\\n            station_signal = signal\\n            break\\n    \\n    if not bin_signal:\\n        frappe.msgprint(f\\\"\\u26a0\\ufe0f No Modbus signal mapped to warehouse {source_warehouse}. Robot command skipped.\\\", indicator=\\\"orange\\\")\\n    elif not station_signal:\\n        frappe.msgprint(\\\"\\u26a0\\ufe0f No Modbus signal found for TO_PICKPACK_STA_2. Robot command skipped.\\\", indicator=\\\"orange\\\")\\n    else:\\n        # Write command signals - catch connection errors if PLC is offline\\n        try:\\n            bin_signal.write_signal(True)\\n            station_signal.write_signal(True)\\n            frappe.msgprint(f\\\"\\u2705 Robot commanded to move {bin_signal.signal_name} to Pick & Pack Station\\\")\\n        except ConnectionError as e:\\n            frappe.msgprint(f\\\"\\u26a0\\ufe0f PLC not connected. Robot command skipped.\\\", indicator=\\\"orange\\\")\\n        except Exception as e:\\n            frappe.msgprint(f\\\"\\u26a0\\ufe0f Failed to send robot command: {str(e)}\\\", indicator=\\\"orange\\\")\\n\"]],\"data_import\":null,\"removed\":[],\"row_changed\":[],\"updater_reference\":null}',NULL,NULL,NULL,NULL),
('tao168gv54','2025-09-06 20:03:07.999573','2025-09-06 20:03:07.999573','Administrator','Administrator',0,0,'System Settings','System Settings','{\"added\":[],\"changed\":[[\"country\",\"\",\"United States\"],[\"language\",\"\",\"en-US\"],[\"time_zone\",null,\"America/New_York\"],[\"currency\",\"\",\"USD\"],[\"date_format\",\"yyyy-mm-dd\",\"mm-dd-yyyy\"],[\"float_precision\",\"\",\"3\"],[\"rounding_method\",\"Banker\'s Rounding (legacy)\",\"Banker\'s Rounding\"],[\"enable_scheduler\",0,1],[\"enable_telemetry\",1,0]],\"data_import\":null,\"removed\":[],\"row_changed\":[],\"updater_reference\":null}',NULL,NULL,NULL,NULL),
